package com.securellm.controller; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.GetMapping; import org.springframework.web.bind.annotation.RestController; import java.io.IOException; import java.net.InetSocketAddress; import java.net.Socket; @RestController public class ConnectivityController { @GetMapping("/check-connectivity") public ResponseEntity<String> checkConnectivity() { try { Socket socket = new Socket(); socket.connect(new InetSocketAddress("8.8.8.8", 53), 2000); socket.close(); return ResponseEntity.ok("Connected to internet"); } catch (IOException e) { return ResponseEntity.status(503).body("No internet connection"); } } }
